Finding a Target Element in a BST
// Finds the specified target element in a binary search tree
// Returns a binary tree object for the target node
public BinaryTree<T> find(T target) {
  TreeNode<T> node = root;
  while (node != null) {
    if (target.equals(node.element)) break;
    if (target.compareTo(node.element) < 0) node = node.left;
    else node = node.right;
  }
  return new LinkedTree<>(node);
}

