// Recursively removes a target node in a binary search tree
private TreeNode<T> remove(TreeNode<T> node, T target) {
  if (node == null) return null;
  if (target.compareTo(node.element) < 0)
                                                           // target is smaller
    node.left = remove(node.left, target);
                                                           // recursive call
  else if (target.compareTo(node.element) > 0)
                                                           // target is larger
    node.right = remove(node.right, target);
                                                           // recursive call
  else { // target is equal to node.element
    // Case 1: Node with only one child or no child
    if (node.left == null) return node.right;
                                                           // No left child
    if (node.right == null) return node.left;
                                                           // No right child
    // Case 2: Node with two children
    node.element = findMin(node.right);
                                                           // find min in right subtree
    node.right = remove(node.right, node.element);
                                                           // recursive call
  }
  return node;
}

