Removing the Minimum Element Node
public T removeMin() { 
// Removes the minimum element node
  if (root == null) return null; 
// empty tree
  if (root.left == null) { 
// if no left child
    T element = root.element; 
// then root has the minimum
    root = root.right; 
// root points to right child
    return element;
  }
  TreeNode<T> parent = root; 
// parent = root node
  TreeNode<T> curr = root.left; 
// current = left child
  while (curr.left != null) { 
// current has a left child
    parent = curr;
    curr = curr.left; 
// leftmost node contains minimum
  }
  parent.left = curr.right; 
// remove the minimum element node
  return curr.element;
}
